style.css:
@-moz-document domain("youtube.com") {
/* 1. HIỂN THỊ CHẤM BI: Nhúng thẳng ảnh đã mã hóa Base64 siêu bảo mật */
    html, body, ytd-app {
        background-image: url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI4MCIgaGVpZ2h0PSI4MCI+PHJlY3Qgd2lkdGg9IjgwIiBoZWlnaHQ9IjgwIiBmaWxsPSIjMkIxODE1Ii8+PGNpcmNsZSBjeD0iMjAiIGN5PSIyMCIgcj0iNiIgZmlsbD0iI0ZGQjZDMSIvPjxjaXJjbGUgY3g9IjYwIiBjeT0iNjAiIHI9IjYiIGZpbGw9IiNGRkI2QzEiLz48L3N2Zz4=") !important;
        background-attachment: fixed !important;
        background-size: auto !important;
        background-repeat: repeat !important;
        background-color: #2B1815 !important;
    }

    /* 2. GIỮ NGUYÊN KHUNG TRONG SUỐT ĐÃ ĐẠT ĐƯỢC */
    *, 
    html[system-icons], 
    html[dark], 
    ytd-app, 
    ytd-page-manager, 
    ytd-browse, 
    #page-manager, 
    #content, 
    #columns, 
    ytd-two-column-browse-results-renderer,
    ytd-rich-grid-renderer,
    #contents,
    #contentContainer {
        --yt-spec-base-background: transparent !important;
        --yt-spec-raised-background: transparent !important;
        --yt-spec-general-background-a: transparent !important;
        --yt-spec-general-background-b: transparent !important;
        --yt-main-app-background-tmp: transparent !important;
        --yt-spec-static-brand-white: transparent !important;
        --yt-spec-brand-background-solid: transparent !important;
        background-color: transparent !important;
    }

    /* 3. THANH MENU TRÊN CÙNG MÀU NÂU MỜ */
    #masthead-container.ytd-app,
    ytd-masthead,
    #background.ytd-masthead,
    #container.ytd-masthead {
        background: rgba(43, 24, 21, 0.95) !important;
        background-color: rgba(43, 24, 21, 0.95) !important;
        backdrop-filter: blur(8px) !important;
        border-bottom: 1px solid rgba(255, 182, 193, 0.15) !important;
    }

    /* 4. THANH MENU BÊN TRÁI TRONG SUỐT */
    ytd-mini-guide-renderer,
    ytd-mini-guide-entry-renderer,
    #guide-content,
    #guide-content.ytd-app,
    ytd-guide-renderer,
    ytd-guide-section-renderer,
    #sections,
    #sections.ytd-guide-renderer,
    #items.ytd-guide-section-renderer,
    #contentContainer.ytd-app,
    ytd-guide-entry-renderer {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* 5. HỆ THỐNG CHỮ MÀU TRẮNG SẮC NÉT */
    #video-title, #title, span, yt-formatted-string, a, p, h1, h2, h3,
    #video-title-link, .title, #metadata-line span, #channel-name yt-formatted-string,
    .ytd-keyword-header-renderer, #content-text, .title.ytd-guide-entry-renderer,
    #guide-section-title {
        --yt-spec-text-primary: #ffffff !important;
        --yt-spec-text-secondary: #e0e0e0 !important;
        color: #ffffff !important;
    }

    /* 6. HỘP NỀN MỜ CHO CÁC THẺ VIDEO */
    ytd-rich-grid-media, ytd-grid-video-renderer, ytd-compact-video-renderer, ytd-rich-item-renderer {
        background: rgba(43, 24, 21, 0.6) !important;
        padding: 12px !important;
        border-radius: 16px !important;
        box-shadow: 0 6px 14px rgba(0,0,0,0.35) !important;
        border: 1px solid rgba(255, 182, 193, 0.12) !important;
    }
}
